  display: block;
  width: 100%;
  height: 76px;
  object-fit: contain;
  background: #f3f1f7;
  border-radius: 4px;
}
.asset-grid span {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 10px;
  margin-top: 6px;
}
.image-controls {
  padding-bottom: 16px;
  border-bottom: 1px solid var(--border);
}

.image-library-dialog {
  width: min(760px, calc(100vw - 64px));
  max-height: 80vh;
  padding: 24px;
  border: 1px solid #dedbe9;
  border-radius: 16px;
  box-shadow: 0 24px 80px #211c3333;
}
.image-library-dialog::backdrop {
  background: #17112566;
}
.image-library-dialog > header {
  display: flex;
  justify-content: space-between;
  align-items: start;
  gap: 24px;
  margin-bottom: 24px;
}
.editor .image-library-dialog h2 {
  margin: 0 0 8px;
}
.editor .image-library-dialog header p {
  margin: 0;
  color: #777386;
}
.image-library-dialog .asset-grid {
  grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
}
.image-library-dialog .asset-grid img {
  height: 130px;
}
.image-library-dialog .asset-grid button[aria-pressed="true"] {
  border-color: #7952ed;
  background: #f0ebff;
}
.image-upload-status {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 100;
  padding: 12px 20px;
  border-radius: 10px;
  background: #31254b;
  color: white;
  box-shadow: 0 8px 24px #211c3333;
}
